def camel_to_snake(s: str) -> str:
    result = []
    prev_char = ''
    for char in s:
        if char.isupper():
            if prev_char and prev_char.islower():
                result.append('_')
            result.append(char.lower())
        else:
            result.append(char)
        prev_char = char
    return ''.join(result)

